  // organization_id is VARCHAR not UUID, structural cleanup needed first.
  `DO $$
   DECLARE
     default_tenant_id UUID := 'a0000000-0000-4000-8000-000000000001';
     tbl TEXT;
     user_fk TEXT;
     fallback_fk TEXT;
     null_count INTEGER;
     config TEXT[] := ARRAY[
       'certifications',  'issuer_user_id',  'holder_user_id',
       'signatories',     'user_id',         '',
       'audit_logs',      'user_id',         '',
       'api_keys',        'user_id',         '',
