       -- (billing service module). See migration 020.
       'did_documents',   'user_id',         '',
       'credential_templates', '',           ''
     ];
     i INTEGER;
   BEGIN
     i := 1;
     WHILE i <= array_length(config, 1) LOOP
       tbl := config[i];
       user_fk := config[i+1];
       fallback_fk := config[i+2];

       IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                      WHERE table_schema='public' AND table_name=tbl) THEN
         i := i + 3;
         CONTINUE;
       END IF;

       IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                      WHERE table_schema='public' AND table_name=tbl
                        AND column_name='tenant_id') THEN
         EXECUTE format('ALTER TABLE %I ADD COLUMN tenant_id UUID', tbl);
       END IF;

       IF user_fk <> '' AND EXISTS (
         SELECT 1 FROM information_schema.columns
          WHERE table_schema='public' AND table_name='users'
            AND column_name='tenant_id'
       ) THEN
         EXECUTE format(
           'UPDATE %I t SET tenant_id = u.tenant_id FROM users u
             WHERE t.tenant_id IS NULL AND t.%I = u.id
               AND u.tenant_id IS NOT NULL', tbl, user_fk);
         IF fallback_fk <> '' THEN
           EXECUTE format(
             'UPDATE %I t SET tenant_id = u.tenant_id FROM users u
               WHERE t.tenant_id IS NULL AND t.%I = u.id
                 AND u.tenant_id IS NOT NULL', tbl, fallback_fk);
         END IF;
       END IF;

       EXECUTE format(
         'UPDATE %I SET tenant_id = $1 WHERE tenant_id IS NULL', tbl)
         USING default_tenant_id;

       BEGIN
         EXECUTE format('ALTER TABLE %I ALTER COLUMN tenant_id SET NOT NULL', tbl);
       EXCEPTION WHEN others THEN NULL;
       END;

       EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%s_tenant_id ON %I(tenant_id)', tbl, tbl);

       EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', tbl);
       EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', tbl);
       -- KS-458: the permissive tenant_isolation policy that was
       -- re-declared here on every boot is REMOVED — migrations
       -- 038 (consolidation) + 039 (fail-closed flip) are the single
       -- authoritative source. Re-declaring it here would silently
       -- revert the fail-closed policy on every gateway restart.
       -- RLS stays ENABLED+FORCED; a table created by this boot path
       -- before 039 has run is default-deny until 039 applies.

       i := i + 3;
     END LOOP;
   END $$`,
];

/** Run a set of migrations against a single database */
interface MigrateResult {
  /** Statements that ran cleanly. */
  applied: number;
  /**
   * Statements that failed for a reason other than the idempotent re-run path.
   * KS-1062 (QA finding F-928-4): this function catches every per-statement
   * error and has never thrown, so a caller could not distinguish "migrated"
   * from "could not connect to the database at all" — a `pg.Pool` does not
   * connect eagerly, so a dead host surfaces as every statement failing in
   * here, and the tenant loop's own catch arm was unreachable code.
   */
  failed: number;
  /** First non-benign error, so the caller can log a cause rather than a count. */
  firstError?: string;
}

async function migrateDatabase(pg: any, connStr: string, dbName: string, migrations: string[]): Promise<MigrateResult> {
  const pool = new pg.Pool({ connectionString: connStr, max: 2, connectionTimeoutMillis: 10000 });
  let applied = 0;
  let failed = 0;
  let firstError: string | undefined;
  try {
    for (const sql of migrations) {
      try {
        await pool.query(sql);
        applied++;
      } catch (err: any) {
        // "already exists" is the idempotent re-run path, not a failure.
        if (!err?.message?.includes('already exists')) {
          failed++;
          if (firstError === undefined) firstError = err?.message?.substring(0, 200);
          // KS-950: warn, not debug. Everything that reaches here is a REAL
          // failure, and at debug it produced one line nobody reads while the
          // caller still summarised the run as complete — which is how the
          // twelve-row user statement could throw on every boot unseen.
          log('warn', `Migration FAILED on ${dbName}`, { error: err?.message?.substring(0, 200) });
        }
      }
    }
  } finally {
    await pool.end();
  }
  return { applied, failed, firstError };
}

/**
 * KS-109: provision the least-privilege `secuura_app` runtime role on Azure.
 *
 * On Azure the runtime services connect to Postgres as `secuuraadmin` (the
 * flexible-server admin + table owner), which is a superuser-equivalent and
 * BYPASSRLS — so RLS gives no isolation (KS-108) and the connection is wildly
 * over-privileged. The fix is to run the *runtime* as a non-admin, NOBYPASSRLS
 * `secuura_app` role while *migrations* keep using the admin/owner connection
 * (this gateway's own — DDL needs it, and the owner is correctly RLS-exempt).
 *
 * This step creates that role + grants the DML privileges the services need on
 * both the main (`secuura`) and platform (`secuura_platform`) DBs. The role is
 * cluster-global, so CREATE runs once (on the main connection); GRANTs are
 * per-DB and run against each pool.
 *
 * Env-guarded + idempotent: a no-op unless APP_DB_PASSWORD is set (sourced from
 * the `secuura-app-db-password` Key Vault secret wired into this gateway). Until
 * that secret is wired AND this gateway is redeployed, landing this code changes
 * nothing at runtime. The role then sits UNUSED until the data services'
 * DATABASE_URL is switched to it — the deliberate cutover documented in
 * `deployment/azure/RLS_ROLE_CUTOVER.md`.
 */
async function provisionAppRole(pg: any, dbUrl: string, platformDbUrl?: string): Promise<void> {
  const appPassword = process.env.APP_DB_PASSWORD;
  if (!appPassword || appPassword === 'app-db-password-not-configured') {
    log('debug', 'APP_DB_PASSWORD not set — skipping secuura_app provisioning (KS-109)');
    return;
  }
  // Escape single quotes for safe SQL literal embedding (' -> ''). The role
  // password is never logged.
  const pw = appPassword.replace(/'/g, "''");

  // 1. Role — create-or-converge on the main connection (roles are global).
  const mainPool = new pg.Pool({ connectionString: dbUrl, max: 1, connectionTimeoutMillis: 10000 });
  try {
    await mainPool.query(`
      DO $$
      BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'secuura_app') THEN
          CREATE ROLE secuura_app WITH LOGIN PASSWORD '${pw}' NOSUPERUSER NOINHERIT NOBYPASSRLS;
        ELSE
          ALTER ROLE secuura_app WITH LOGIN PASSWORD '${pw}' NOSUPERUSER NOINHERIT NOBYPASSRLS;
        END IF;
      END $$;
    `);
    log('info', 'secuura_app role ensured (KS-109)');
  } catch (err: any) {
    log('warn', 'secuura_app role provisioning failed', { error: err?.message });
  } finally {
    await mainPool.end();
  }

  // 2. Grants — per-DB DML (no DDL), on each app database that exists.
  const grantSql = (db: string) => `
    GRANT CONNECT ON DATABASE "${db}" TO secuura_app;
    GRANT USAGE ON SCHEMA public TO secuura_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO secuura_app;
    GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO secuura_app;
    GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO secuura_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO secuura_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO secuura_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO secuura_app;
  `;
  const targets = [dbUrl, ...(platformDbUrl ? [platformDbUrl] : [])];
  for (const connStr of targets) {
    let dbName = 'secuura';
    try { dbName = new URL(connStr).pathname.replace(/^\//, '') || 'secuura'; } catch { /* keep default */ }
    const pool = new pg.Pool({ connectionString: connStr, max: 1, connectionTimeoutMillis: 10000 });
    try {
      await pool.query(grantSql(dbName));
      log('info', `secuura_app grants applied on ${dbName} (KS-109)`);
    } catch (err: any) {
      log('warn', `secuura_app grants failed on ${dbName}`, { error: err?.message });
    } finally {
      await pool.end();
    }
  }
}

export async function runStartupMigrations(): Promise<void> {
  // KS-109: the gateway runs all DDL/migrations and provisions the secuura_app
  // role, so the migration connection must stay on the admin/owner role even
  // after the runtime services move to the least-privilege role. MIGRATION_DATABASE_URL
  // (admin) is wired on the gateway only; it falls back to DATABASE_URL so this is
  // backward-compatible and inert until that env is set (Stage 1). See
  // deployment/azure/RLS_ROLE_CUTOVER.md.
  const dbUrl = process.env.MIGRATION_DATABASE_URL || process.env.DATABASE_URL;
  const platformDbUrl = process.env.MIGRATION_PLATFORM_DATABASE_URL || process.env.PLATFORM_DATABASE_URL;

  if (!dbUrl) {
    log('warn', 'DATABASE_URL not set — skipping startup migrations');
    return;
  }

  const pg = require('pg');

  // KS-30: stage 1 — file-based migrations from migrations/*.sql.
  // The Dockerfile copies the directory into the image at /app/migrations.
  // Files containing "platform" route to the platform DB; others to main.
  // Tracked per-DB via _secuura_migrations(filename) so re-runs are idempotent.
  const migrationsDir = findMigrationsDir();
  let fileMigrations: LoadedMigration[] = [];
  if (migrationsDir) {
    fileMigrations = loadMigrationFiles(migrationsDir);
    log('info', `loaded ${fileMigrations.length} migration files from ${migrationsDir}`);
  } else {
    log('warn', 'no migrations directory found — skipping file-based stage');
  }

  if (fileMigrations.length > 0) {
    try {
      // KS-950: the word "complete" is reserved for a run with zero failures.
      // A summary that reads the same whether 0 or 5 migrations failed is a
      // claim wider than the run, so a failed count changes the level AND the words.
      const fileMain = await applyFileMigrations(pg, dbUrl, 'main', fileMigrations);
      log(
        fileMain.failed > 0 ? 'warn' : 'info',
        fileMain.failed > 0
          ? `File-based main DB migrations INCOMPLETE — ${fileMain.failed} FAILED`
          : `File-based main DB migrations complete`,
        { applied: fileMain.applied, failed: fileMain.failed },
      );
    } catch (err: any) {
      log('warn', 'File-based main DB migrations failed', { error: err?.message });
    }
    if (platformDbUrl) {
      try {
        const filePlatform = await applyFileMigrations(pg, platformDbUrl, 'platform', fileMigrations);
        log(
          filePlatform.failed > 0 ? 'warn' : 'info',
          filePlatform.failed > 0
            ? `File-based platform DB migrations INCOMPLETE — ${filePlatform.failed} FAILED`
            : `File-based platform DB migrations complete`,
          { applied: filePlatform.applied, failed: filePlatform.failed },
        );
      } catch (err: any) {
        log('warn', 'File-based platform DB migrations failed', { error: err?.message });
      }
    }
  }

  // KS-30: stage 2 — legacy CORE_MIGRATIONS array (transitional fallback).
  // Every new migration should land as a file under migrations/ and the
  // matching CORE_MIGRATIONS entry should be removed in the same PR.
  // 1. Migrate main database
  try {
    const { applied, failed } = await migrateDatabase(pg, dbUrl, 'main', CORE_MIGRATIONS);
    // KS-950: "complete" only when nothing failed (the count itself is #932's).
    log(
      failed > 0 ? 'warn' : 'info',
      failed > 0 ? `Main DB migrations INCOMPLETE — ${failed} FAILED` : `Main DB migrations complete`,
      { applied, failed },
    );

    // KS-962: this statement CREATES NO ROW. The twelve per-client users are
    // created by auth's seedDemoUsers (services/auth/src/repositories/userRepo.ts),
    // which encrypts email, sets email_lookup_hash and owns names, role and
    // status. The INSERT that used to live here wrote PLAINTEXT into an
    // encrypted column and never set the lookup hash (KS-962, "what not to
    // do"); and on the deployed schema its ON CONFLICT (email) target does not
    // exist (users.email has no unique index — uniqueness lives on
    // email_lookup_hash), so it raised 42P10 on every boot and seeded nothing
    // (KS-950). What survives is its only defensible job: re-sync tenant_id /
    // tenant_slug on rows that ALREADY exist, keyed on the primary key. The
    // IS DISTINCT FROM guard makes a no-change boot write nothing, so rowCount
    // is the number of rows actually re-synced. Its "so document FK constraints
    // work" justification was false on the deployed schema, where that FK is
    // not declared (the two schema sources disagree; tracked separately).
    // Suite: scripts/__tests__/ks949_main_seed_idempotence.test.sh — both
    // seeders, both orders, on a real PostgreSQL built from docker/init + migrations.
    const mainPool = new pg.Pool({ connectionString: dbUrl, max: 2, connectionTimeoutMillis: 10000 });
    try {
      const resync = await mainPool.query(`
        UPDATE users AS u SET
          tenant_id = v.tenant_id::uuid,
          tenant_slug = v.tenant_slug,
          updated_at = NOW()
        FROM (VALUES
          ('a0000000-0000-4000-8000-000000000060', 'a0000000-0000-4000-8000-000000000099', 'secuura-co'),
          ('c1000000-0000-4000-8000-000000000001', 'b1000000-0000-4000-8000-000000000001', 'oxford-university'),
          ('c1000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000001', 'oxford-university'),
          ('c1000000-0000-4000-8000-000000000003', 'b1000000-0000-4000-8000-000000000001', 'oxford-university'),
          ('c2000000-0000-4000-8000-000000000001', 'b2000000-0000-4000-8000-000000000001', 'bupa-health-uk'),
          ('c2000000-0000-4000-8000-000000000002', 'b2000000-0000-4000-8000-000000000001', 'bupa-health-uk'),
          ('c2000000-0000-4000-8000-000000000003', 'b2000000-0000-4000-8000-000000000001', 'bupa-health-uk'),
          ('c2000000-0000-4000-8000-000000000004', 'b2000000-0000-4000-8000-000000000001', 'bupa-health-uk'),
          ('c3000000-0000-4000-8000-000000000001', 'b3000000-0000-4000-8000-000000000001', 'apex-consulting'),
          ('c3000000-0000-4000-8000-000000000002', 'b3000000-0000-4000-8000-000000000001', 'apex-consulting'),
          ('c4000000-0000-4000-8000-000000000001', 'b4000000-0000-4000-8000-000000000001', 'greenfield-university'),
          ('c5000000-0000-4000-8000-000000000001', 'b5000000-0000-4000-8000-000000000001', 'delta-corp')
        ) AS v(id, tenant_id, tenant_slug)
        WHERE u.id = v.id::uuid
          AND (u.tenant_id IS DISTINCT FROM v.tenant_id::uuid OR u.tenant_slug IS DISTINCT FROM v.tenant_slug)
      `);
      log('info', 'Per-client user tenant re-sync complete (main DB)', { resynced: resync.rowCount });
    } catch (seedErr: any) {
      // KS-950: warn, not debug. This arm fired on every boot for as long as the
      // 42P10 existed and left no trace at any level the demo reads.
      log('warn', 'Per-client user tenant re-sync FAILED (main DB)', { error: seedErr?.message?.substring(0, 200) });
    } finally {
      await mainPool.end();
    }
  } catch (err: any) {
    log('warn', 'Main DB migrations failed', { error: err?.message });
  }

  // 2. Migrate platform database
  if (platformDbUrl) {
    try {
      const platformMigrations = [
        `CREATE EXTENSION IF NOT EXISTS "uuid-ossp"`,
        // Cross-tenant document hash lookup
        `CREATE TABLE IF NOT EXISTS platform_document_registry (
          id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
          content_hash VARCHAR(128) NOT NULL,
          document_id TEXT, tenant_id TEXT, tenant_slug TEXT,
          document_type VARCHAR(100), title VARCHAR(500),
          status VARCHAR(20) DEFAULT 'draft',
          created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW()
        )`,
        `CREATE INDEX IF NOT EXISTS idx_pdr_hash ON platform_document_registry(content_hash)`,
        `CREATE INDEX IF NOT EXISTS idx_pdr_doc ON platform_document_registry(document_id)`,
        // KS-39 #4: see the same fix on the main DB above — without this
        // UNIQUE index the verification.ts ON CONFLICT clause errors.
        `DELETE FROM platform_document_registry a USING platform_document_registry b
         WHERE a.id > b.id AND a.content_hash = b.content_hash
           AND COALESCE(a.tenant_id, '') = COALESCE(b.tenant_id, '')`,
        `CREATE UNIQUE INDEX IF NOT EXISTS uq_pdr_hash_tenant ON platform_document_registry(content_hash, tenant_id)`,
        `CREATE TABLE IF NOT EXISTS platform_document_type_templates (
          id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
          name VARCHAR(255) NOT NULL, code VARCHAR(100) UNIQUE NOT NULL,
          description TEXT, category VARCHAR(100), is_active BOOLEAN DEFAULT TRUE,
          creator_verification_level VARCHAR(50) DEFAULT 'basic',
          owner_verification_level VARCHAR(50) DEFAULT 'basic',
          viewer_verification_level VARCHAR(50) DEFAULT 'none',
          verifier_verification_level VARCHAR(50) DEFAULT 'standard',
          require_mfa BOOLEAN DEFAULT FALSE, require_kyc BOOLEAN DEFAULT FALSE,
          require_wallet_signature BOOLEAN DEFAULT FALSE,
          auto_anchor BOOLEAN DEFAULT TRUE, anchor_network VARCHAR(50) DEFAULT 'preprod',
          metadata_schema JSONB DEFAULT '[]',
          created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW()
        )`,
      ];
      const { applied, failed } = await migrateDatabase(pg, platformDbUrl, 'platform', platformMigrations);
      // KS-950: "complete" only when nothing failed (the count itself is #932's).
      log(
        failed > 0 ? 'warn' : 'info',
        failed > 0 ? `Platform DB migrations INCOMPLETE — ${failed} FAILED` : `Platform DB migrations complete`,
        { applied, failed },
      );

      // Seed Secuura Co. and client tenants (idempotent — ON CONFLICT DO NOTHING)
      const pSeedPool = new pg.Pool({ connectionString: platformDbUrl, max: 2, connectionTimeoutMillis: 10000 });
      try {
        await pSeedPool.query(`
          INSERT INTO tenants (id, name, slug, domain, industry, country, status) VALUES
            ('a0000000-0000-4000-8000-000000000099', 'Secuura Co.', 'secuura-co', 'secuura.ai', 'Technology', 'United Kingdom', 'active'),
            ('b1000000-0000-4000-8000-000000000001', 'Oxford University', 'oxford-university', 'oxford-test.invalid', 'Education', 'United Kingdom', 'active'),
            ('b2000000-0000-4000-8000-000000000001', 'BUPA Health UK', 'bupa-health-uk', 'bupa-test.invalid', 'Healthcare', 'United Kingdom', 'active'),
            ('b3000000-0000-4000-8000-000000000001', 'Apex Consulting', 'apex-consulting', 'apex-test.invalid', 'Consulting', 'United Kingdom', 'active'),
            ('b4000000-0000-4000-8000-000000000001', 'Greenfield University', 'greenfield-university', 'greenfield-test.invalid', 'Education', 'United Kingdom', 'active'),
            ('b5000000-0000-4000-8000-000000000001', 'Delta Corp', 'delta-corp', 'delta-corp-test.invalid', 'Technology', 'United Kingdom', 'active')
          ON CONFLICT (slug) DO NOTHING
        `);

        // Ensure all tenants have a tenant_config entry pointing to the shared 'secuura' database.
        // On Azure there is a single DB; per-tenant DBs are not provisioned.
        const dbUrl = process.env.DATABASE_URL || '';
        let sharedDbName = 'secuura';
        try { sharedDbName = new URL(dbUrl).pathname.replace(/^\//, '') || 'secuura'; } catch {}
        const sharedDbHost = (() => { try { return new URL(dbUrl).hostname; } catch { return 'postgres'; } })();
        const sharedDbPort = (() => { try { return parseInt(new URL(dbUrl).port || '5432'); } catch { return 5432; } })();

        const tenantIds = [
          '00000000-0000-4000-8000-000000000001',  // default
          'a0000000-0000-4000-8000-000000000001',  // default (alt ID from Docker seed)
          'a0000000-0000-4000-8000-000000000099',  // secuura-co
          'b1000000-0000-4000-8000-000000000001',  // oxford
          'b2000000-0000-4000-8000-000000000001',  // bupa
          'b3000000-0000-4000-8000-000000000001',  // apex
          'b4000000-0000-4000-8000-000000000001',  // greenfield
          'b5000000-0000-4000-8000-000000000001',  // delta
        ];
        for (const tid of tenantIds) {
          try {
            await pSeedPool.query(
              `INSERT INTO tenant_config (tenant_id, db_name, db_host, db_port, token_location_type)
               VALUES ($1, $2, $3, $4, 'manual')
               ON CONFLICT (tenant_id) DO UPDATE SET db_name = $2, db_host = $3, db_port = $4`,
              [tid, sharedDbName, sharedDbHost, sharedDbPort]
            );
          } catch {}
        }

        log('info', 'Platform tenant seed complete (Secuura Co. + 5 client tenants + config)');
      } catch (seedErr: any) {
        log('debug', 'Platform tenant seed skipped', { error: seedErr?.message?.substring(0, 80) });
      } finally {
        await pSeedPool.end();
      }
    } catch (err: any) {
      log('warn', 'Platform DB migrations failed', { error: err?.message });
    }

    // 3. Migrate ALL tenant databases
    if (process.env.MULTI_TENANCY_ENABLED === 'true') {
      try {
        const pPool = new pg.Pool({ connectionString: platformDbUrl, max: 2 });
        const result = await pPool.query(
          `SELECT t.id, t.slug, tc.db_name, tc.db_host, tc.db_port
           FROM tenants t LEFT JOIN tenant_config tc ON t.id = tc.tenant_id
           WHERE t.status = 'active' AND tc.db_name IS NOT NULL`
        );
        await pPool.end();

        // Parse the main DB URL to get credentials
        const url = new URL(dbUrl);
        const baseUser = url.username;
        const basePass = url.password;
        const baseHost = url.hostname;
        const basePort = url.port || '5432';

        let migrated = 0;
        let failedTenants = 0;
        let skipped = 0;

        for (const tenant of result.rows) {
          const tenantDbName = tenant.db_name;
          const tenantHost = tenant.db_host || baseHost;
          const tenantPort = tenant.db_port || basePort;
          const tenantConnStr = `postgresql://${baseUser}:${basePass}@${tenantHost}:${tenantPort}/${tenantDbName}?sslmode=require`;

          try {
            const outcome = await migrateDatabase(pg, tenantConnStr, tenantDbName, CORE_MIGRATIONS);
            // KS-1062 (F-928-4): migrateDatabase never throws, so incrementing
            // `migrated` on return counted every tenant — including one whose
            // database does not exist, where the connection failure surfaces as
            // every statement failing inside it. Only a clean run counts.
            if (outcome.failed > 0) {
              failedTenants++;
              log('warn', `Tenant ${tenant.slug} migrations FAILED`, {
                db: tenantDbName,
                applied: outcome.applied,
                failed: outcome.failed,
                error: outcome.firstError,
              });
            } else {
              migrated++;
            }
          } catch (err: any) {
            log('debug', `Tenant ${tenant.slug} migration skipped`, { error: err?.message?.substring(0, 60) });
            skipped++;
          }
        }

        // KS-950: #932 made a failed tenant countable; "complete" is still
        // reserved for a run in which no tenant failed.
        log(
          failedTenants > 0 ? 'warn' : 'info',
          failedTenants > 0
            ? `Tenant DB migrations INCOMPLETE — ${failedTenants} tenant(s) FAILED`
            : `Tenant DB migrations complete`,
          { migrated, failed: failedTenants, skipped, total: result.rows.length },
        );
      } catch (err: any) {
        log('warn', 'Tenant DB migration scan failed', { error: err?.message });
      }
    }
  }

  // KS-109: provision the least-privilege secuura_app runtime role. Env-guarded
  // (APP_DB_PASSWORD) + idempotent — a no-op until the Key Vault secret is wired
  // into this gateway and the data services' DATABASE_URL is switched to it (see
  // deployment/azure/RLS_ROLE_CUTOVER.md). The migrations above keep running as
  // the admin/owner role, which is correct: DDL needs it, owner is RLS-exempt.
  await provisionAppRole(pg, dbUrl, platformDbUrl);
}

/**
 * `vault_entries` has exactly ONE owner, and it is not this file (KS-667; QA ask 2 / F-4).
 *
 * WHY THIS EXISTS AS A TEST. KS-667's whole point is that `vault_entries` was created in two
 * places with two different shapes: runtime DDL in `startup-migrations.ts` and the versioned
 * `migrations/033_…sql`. The runtime copy was removed and replaced with a comment —
 * "Do not reintroduce a CREATE TABLE for vault_entries here."
 *
 * That comment is the SAME CATEGORY OF CONTROL that produced the ticket. 033's own header
 * asserted a fact about this file which was false when it was written and stayed false across
 * 26 commits, because nothing checked it. Replacing a false comment with a true one changes
 * nothing about why nobody would notice the next drift. This does.
 *
 * THE INSTRUMENT CONTROL IS FIRST. A scan of an empty or mis-imported array would report "no
 * vault_entries" and pass vacuously — indistinguishable from the property holding. So the array
 * must first be proven non-empty AND proven to contain the tables it really does own.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { CORE_MIGRATIONS } from '../startup-migrations';

describe('KS-667 — vault_entries is owned by migrations/, never by runtime DDL', () => {
  it('CONTROL: the array is loaded and really does carry core DDL', () => {
    // If this is red the scan below cannot mean anything.
    expect(Array.isArray(CORE_MIGRATIONS)).toBe(true);
    expect(CORE_MIGRATIONS.length).toBeGreaterThan(5);
    expect(CORE_MIGRATIONS.some((m) => /CREATE TABLE IF NOT EXISTS documents\b/i.test(m))).toBe(true);
  });

  it('no CORE_MIGRATIONS entry mentions vault_entries, in any casing', () => {
    const offenders = CORE_MIGRATIONS.filter((m) => /vault_entries/i.test(m));
    // Named rather than counted: a failure should say WHICH statement reintroduced it.
    expect(offenders.map((m) => m.replace(/\s+/g, ' ').trim().slice(0, 120))).toEqual([]);
  });

  it('and does not reach it under another name — no CREATE TABLE for a vault-ish table', () => {
    // A rename is the obvious way round the assertion above, so the class is covered too.
    const suspicious = CORE_MIGRATIONS.filter((m) => /CREATE TABLE[^;]*\bvault\w*/i.test(m));
    expect(suspicious.map((m) => m.replace(/\s+/g, ' ').trim().slice(0, 120))).toEqual([]);
  });
});

/**
 * QA F-6 (s99). Making 044's step 6 additive removed the only thing that would ever
 * re-assert 039's policy text: 044 now creates the policy when absent and leaves it
 * alone when present, and nothing compares the two. The equality was measured once,
 * by hand, and pinned nowhere — so a future edit to 039 would silently give
 * 039-environments and repaired environments DIFFERENT policies on the table holding
 * tokenised PII.
 *
 * This reads BOTH migrations and compares the policy bodies, so the equality is
 * derivable by anyone rather than being a number in a session log. The previous
 * reviewer could not re-derive the "544 characters" claim; this is the answer to that.
 */
describe('KS-667 / F-6 — 039 and 044 must state the SAME tenant_isolation policy', () => {
  /** Pull the USING/WITH CHECK body out of a `CREATE POLICY tenant_isolation` block. */
  const policyBody = (sql: string): string => {
    const start = sql.indexOf('CREATE POLICY tenant_isolation');
    expect(start).toBeGreaterThanOrEqual(0);
    const body = sql.slice(start);
    const end = body.indexOf('$p$');
    expect(end).toBeGreaterThan(0);
    return body
      .slice(0, end)
      // 039 templates the table name with %I; 044 names it literally. Normalise that
      // one deliberate difference and nothing else.
      .replace('CREATE POLICY tenant_isolation ON %I', 'CREATE POLICY tenant_isolation ON T')
      .replace('CREATE POLICY tenant_isolation ON vault_entries', 'CREATE POLICY tenant_isolation ON T')
      .replace(/\s+/g, ' ')
      .trim();
  };

  const read = (name: string): string =>
    readFileSync(join(__dirname, '../../../../migrations', name), 'utf8');

  it('the two policy bodies are identical once whitespace is normalised', () => {
    const from039 = policyBody(read('039_rls_fail_closed.sql'));
    const from044 = policyBody(read('044_vault_entries_repair.sql'));

    // Both must be substantial — an empty match on either side would make the
    // comparison below pass vacuously.
    expect(from039.length).toBeGreaterThan(200);
    expect(from044.length).toBeGreaterThan(200);
    expect(from039).toBe(from044);
  });

  it('CONTROL: the comparison detects a divergence — through policyBody, not around it', () => {
    // QA F-6: the previous version of this control altered policyBody's OUTPUT —
    //
    //     const altered = policyBody(read(...)).replace("'platform_admin'", ...)
    //     expect(altered).not.toBe(from039)
    //
    // — which asserts only that String.prototype.replace changes a string. It could not
    // fail, and in particular it could NOT detect the one thing its own comment claimed
    // it guarded against: a policyBody that flattens everything to the same value. A
    // constant-returning policyBody passed it.
    //
    // The divergence is now injected into the INPUT and pushed THROUGH the function, so
    // a flattening normaliser makes the two outputs equal and this control goes red.
    const raw039 = read('039_rls_fail_closed.sql');

    // The literal must live INSIDE the extracted body, or mutating it proves nothing
    // about policyBody. This assertion is not decoration: the first draft of this
    // control used `.replace()` (first occurrence only) and 039 mentions
    // 'platform_admin' in a header COMMENT at line 11, long before the policy at :117 —
    // so the mutation landed outside the slice, both outputs were identical, and the
    // control failed. `replaceAll` fixes the mutation; this line stops the same mistake
    // silently returning if either file is reordered.
    expect(policyBody(raw039)).toContain("'platform_admin'");

    const diverged = raw039.replaceAll("'platform_admin'", "'platform_operator'");

    // The mutation must actually have applied — otherwise the comparison below would be
    // comparing a string with itself and passing for the wrong reason.
    expect(diverged).not.toBe(raw039);

    expect(policyBody(diverged)).not.toBe(policyBody(raw039));
  });

  it('both bodies still fail CLOSED — an unset GUC grants nothing', () => {
    // The property the shared text exists for, asserted rather than assumed equal.
    for (const name of ['039_rls_fail_closed.sql', '044_vault_entries_repair.sql']) {
      const body = policyBody(read(name));
      expect(body).toContain("current_setting('app.current_tenant_id', true) IS NOT NULL");
      expect(body).toContain("current_setting('app.current_tenant_id', true) <> ''");
      expect(body).toContain("current_setting('app.tenant_scope_bypass', true) = 'platform_admin'");
    }
  });
});
